components.css:
.ds-report-table-container {
  overflow: auto;
  max-height: 560px;
  scrollbar-gutter: stable;
  border: 1px solid var(--border);
  margin-top: 16px;
  outline-offset: 3px;
}
.ds-report-table {
  border-collapse: collapse;
  font-size: 12px;
  line-height: 1.5;
  min-width: 540px;
}
.ds-report-table th,
.ds-report-table td {
  padding: 12px 14px;
  text-align: left;
  vertical-align: top;
  white-space: normal;
}
.ds-report-table thead th {
  color: var(--muted-foreground);
  font-weight: 500;
  position: sticky;
  top: 0;
  background: var(--card);
  z-index: 1;
}
.ds-report-table td {
  font-variant-numeric: tabular-nums;
}
.ds-report-table td:first-child {
  font-weight: 500;
  max-width: 300px;
  overflow-wrap: anywhere;
}
.ds-report-table tr {
  border-bottom: 1px solid var(--border);
}
.ds-report-table tbody tr:hover {
  background: var(--secondary);
}
.ds-report-table caption {
  padding: 10px 14px;
  text-align: left;
  color: var(--muted-foreground);
  font-size: 11px;
}
